package com.estoqueinteligente.supplier;
import java.util.List;import org.springframework.data.domain.Sort;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.estoqueinteligente.common.ResourceNotFoundException;
@Service public class SupplierService{private final SupplierRepository repository;public SupplierService(SupplierRepository repository){this.repository=repository;}@Transactional(readOnly=true)public List<SupplierResponse> findAll(){return repository.findAll(Sort.by("name")).stream().map(SupplierResponse::new).toList();}@Transactional(readOnly=true)public SupplierResponse findById(Long id){return new SupplierResponse(getEntity(id));}@Transactional public SupplierResponse create(SupplierRequest request){Supplier s=new Supplier();apply(s,request);return new SupplierResponse(repository.save(s));}@Transactional public SupplierResponse update(Long id,SupplierRequest request){Supplier s=getEntity(id);apply(s,request);return new SupplierResponse(repository.save(s));}@Transactional public void delete(Long id){repository.delete(getEntity(id));repository.flush();}@Transactional(readOnly=true)public Supplier getEntity(Long id){return repository.findById(id).orElseThrow(()->new ResourceNotFoundException("Fornecedor não encontrado"));}private void apply(Supplier s,SupplierRequest r){s.setName(r.getName().trim());s.setPhone(normalize(r.getPhone()));s.setEmail(normalize(r.getEmail()));s.setContactPerson(normalize(r.getContactPerson()));s.setNotes(normalize(r.getNotes()));}private String normalize(String value){return value==null||value.isBlank()?null:value.trim();}}
